mapper.select:
SELECT A.CONT_ID AS contId , A.SALES_ID AS salesId , A.CONT_NM AS contNm , A.CONT_AMT AS contAmt , DATE_FORMAT(A.START_DT, '%Y-%m-%d') AS startDt , DATE_FORMAT(A.END_DT, '%Y-%m-%d') AS endDt , DATE_FORMAT(A.CONT_DT, '%Y-%m-%d') AS contDt , A.EMP_ID AS picUserId , B.EMP_NM AS picUserNm , A.CONT_STATUS AS contStatus , S.CUST_ID AS custId , C.CUST_NM as custNm FROM TB_CONTRACT A LEFT JOIN TB_SALES S ON A.SALES_ID = S.SALES_ID LEFT JOIN TB_CUSTOMER C ON S.CUST_ID = C.CUST_ID LEFT JOIN TB_EMP B ON A.EMP_ID = B.EMP_ID WHERE A.DEL_YN = 'N'
AND A.CONT_NM LIKE CONCAT('%', #{searchKeyword}, '%')
ORDER BY A.CONT_ID DESC LIMIT #{recordCountPerPage} OFFSET #{firstIndex}

mapper.insert:
INSERT INTO TB_CONTRACT (
    SALES_ID, CONT_NM, CONT_AMT, START_DT, END_DT, CONT_DT, EMP_ID, CONT_STATUS, CONT_REMARK
) VALUES (
    #{salesId}, #{contNm}, #{contAmt}, NULLIF(#{startDt},''), NULLIF(#{endDt},''), NULLIF(#{contDt},''), #{picUserId}, #{contStatus}, #{contRemark}
)

mapper.update:
UPDATE TB_CONTRACT SET
      SALES_ID = #{salesId}
    , CONT_NM = #{contNm}
    , CONT_AMT = #{contAmt}
    , START_DT = NULLIF(#{startDt}, '')
    , END_DT = NULLIF(#{endDt}, '')
    , CONT_DT = NULLIF(#{contDt}, '')
    , EMP_ID = #{picUserId}
    , CONT_STATUS = #{contStatus}
    , CONT_REMARK = #{contRemark}
    , LAST_UPDUSR_ID = #{lastUpdusrId}
WHERE CONT_ID = #{contId}

UPDATE TB_CONTRACT SET 
      DEL_YN = 'Y'
    , LAST_UPDUSR_ID = #{lastUpdusrId}
WHERE CONT_ID = #{contId}

UPDATE TB_CONTRACT 
   SET CONT_STATUS = #{contStatus}
 WHERE CONT_ID = #{selectedId}
